using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.EntityFrameworkCore;
using InfinityUrban.Web;
using Stayline;
static class UnifiedChecks
{
 public static async Task Run(HttpClient client,FakeSupabase auth,UnifiedTransport remote,IServiceProvider services,Action<bool,string> check,Func<Task<string>> token,Func<string,object,string?,Task<HttpResponseMessage>> post)
 {
  using var status=await client.GetAsync("/api/status");using var statusBody=JsonDocument.Parse(await status.Content.ReadAsStringAsync());check(statusBody.RootElement.GetProperty("environment").GetString()=="production","Approved operational API remains configured for production");
  using var page=await client.GetAsync("/operacoes");check(page.IsSuccessStatusCode&&!(await page.Content.ReadAsStringAsync()).Contains("<iframe"),"Operations remain native to the Urban Infinity site");
  using var operationalScript=await client.GetAsync("/operations-original.js");check(operationalScript.IsSuccessStatusCode&&operationalScript.Content.Headers.ContentType?.MediaType=="text/javascript","The unified application serves the unchanged operational interface from its internal Channex module");
  using var initial=await client.GetAsync("/api/accommodations");var initialText=await initial.Content.ReadAsStringAsync();check(initial.IsSuccessStatusCode&&initialText.Contains("property-photo-must-not-show")&&initialText.Contains("room-photo"),"Catalog reads separate property and room galleries from Channex");
  var csrf=await token();var building=new BuildingInput(Guid.NewGuid(),"Prédio remoto","BRL","America/Sao_Paulo","Rua Prédio 100","São Paulo","SP","BR","01234-000","contact@example.com","+5511999999999","Descrição remota");
  auth.CurrentRole="funcionario";check((await post("/api/accommodations/properties",building,csrf)).StatusCode==HttpStatusCode.Forbidden,"Staff cannot create remote properties");check((await post("/API/PROPERTIES/",new{name="Blocked",kind="hotel",currency="BRL",timeZoneId="UTC"},csrf)).StatusCode==HttpStatusCode.Forbidden,"Original API role checks cover casing and trailing slash");auth.CurrentRole="master";
  using var created=await post("/api/accommodations/properties",building,csrf);using var createdDoc=JsonDocument.Parse(await created.Content.ReadAsStringAsync());check(created.IsSuccessStatusCode&&createdDoc.RootElement.GetProperty("confirmed").GetBoolean(),"Saving a building immediately creates and reads it back from Channex, before any rooms exist");var id=createdDoc.RootElement.GetProperty("id").GetGuid();
  var propertyBody=remote.Writes.Single(w=>w.Resource=="properties").Body.GetProperty("property");check(propertyBody.GetProperty("address").GetString()==building.Address&&propertyBody.GetProperty("email").GetString()==building.Email&&propertyBody.GetProperty("phone").GetString()==building.Phone&&propertyBody.GetProperty("content").GetProperty("description").GetString()==building.Description,"Property creation sends contact, address and description in the original remote create request");
  var settings=propertyBody.GetProperty("settings");check(settings.GetProperty("state_length").GetInt32()==500&&!settings.GetProperty("allow_availability_autoupdate_on_modification").GetBoolean()&&!settings.GetProperty("allow_availability_autoupdate_on_cancellation").GetBoolean(),"New property creation preserves the approved synchronization settings");
  check((await post("/api/accommodations/properties",building,csrf)).IsSuccessStatusCode&&remote.Writes.Count(w=>w.Resource=="properties")==1,"Repeating a confirmed creation cannot duplicate the building");
  using(var scope=services.CreateScope()){await using var db=await scope.ServiceProvider.GetRequiredService<IDbContextFactory<AppDb>>().CreateDbContextAsync();check(await db.Properties.CountAsync()==0&&await db.RoomTypes.CountAsync()==0,"Remote accommodation creation writes no local property or room business records");var files=scope.ServiceProvider.GetRequiredService<CatalogFiles>();check(!Directory.EnumerateFiles(files.DirectoryPath).Any(p=>Path.GetFileName(p).StartsWith("building-")),"No local building content is saved");}
  using var photoRequest=new HttpRequestMessage(HttpMethod.Post,"/api/accommodations/photos");photoRequest.Headers.Add("X-CSRF-Token",csrf);var multipart=new MultipartFormDataContent();multipart.Add(new ByteArrayContent(new byte[]{255,216,255,0,0,0,0,0,0,0,0,0}),"photo","test.jpg");photoRequest.Content=multipart;using var uploaded=await client.SendAsync(photoRequest);using var photoDoc=JsonDocument.Parse(await uploaded.Content.ReadAsStringAsync());var ticket=photoDoc.RootElement.GetProperty("ticket").GetString()!;
  var fullBuilding=building with{OperationId=Guid.NewGuid(),Title="Prédio com conteúdo",ImportantInformation="Check-in após 15h. Não fumar.",Facilities=[Guid.Parse(UnifiedTransport.PropertyFacility)],PhotoTickets=Enumerable.Repeat(ticket,30).ToArray(),LogoTicket=ticket};
  var propertiesBefore=remote.Writes.Count(w=>w.Resource=="properties");
  check((await post("/api/accommodations/properties",fullBuilding with{PhotoTickets=Enumerable.Repeat(ticket,31).ToArray()},csrf)).StatusCode==HttpStatusCode.BadRequest&&remote.Writes.Count(w=>w.Resource=="properties")==propertiesBefore,"Property gallery rejects 31 images before creating a remote property");
  check((await post("/api/accommodations/properties",fullBuilding with{LogoTicket="untrusted-logo-ticket"},csrf)).StatusCode==HttpStatusCode.BadRequest&&remote.Writes.Count(w=>w.Resource=="properties")==propertiesBefore,"Property logo accepts only an authenticated upload ticket");
  using var fullCreated=await post("/api/accommodations/properties",fullBuilding,csrf);using var fullDoc=JsonDocument.Parse(await fullCreated.Content.ReadAsStringAsync());check(fullCreated.IsSuccessStatusCode&&fullDoc.RootElement.GetProperty("confirmed").GetBoolean(),"Full property content is sent immediately and confirmed by a remote read");var fullId=fullDoc.RootElement.GetProperty("id").GetGuid();
  var fullPayload=remote.Writes.Last(w=>w.Resource=="properties").Body.GetProperty("property");check(fullPayload.GetProperty("content").GetProperty("photos").GetArrayLength()==30&&fullPayload.GetProperty("logo_url").GetString()=="https://img.channex.io/uploaded-room-photo/","Property creation sends a separate logo and a gallery of 30 ordered images");
  check(fullPayload.GetProperty("facilities")[0].GetGuid()==Guid.Parse(UnifiedTransport.PropertyFacility)&&fullPayload.GetProperty("content").GetProperty("important_information").GetString()==fullBuilding.ImportantInformation,"Property facilities and important information use the correct Channex fields");
  var fullWrites=remote.Writes.Count;check((await post("/api/accommodations/properties",fullBuilding,csrf)).IsSuccessStatusCode&&remote.Writes.Count==fullWrites,"Retrying a completed property with content cannot duplicate its gallery");
  using(var result=await client.GetAsync("/api/accommodations")){using var resultDoc=JsonDocument.Parse(await result.Content.ReadAsStringAsync());var property=resultDoc.RootElement.GetProperty("properties").EnumerateArray().Single(p=>p.GetProperty("id").GetGuid()==fullId);check(property.GetProperty("photos").GetArrayLength()==30&&property.GetProperty("importantInformation").GetString()==fullBuilding.ImportantInformation&&property.GetProperty("facilities")[0].GetProperty("title").GetString()=="Elevador"&&property.GetProperty("logoUrl").GetString()!.StartsWith("https://"),"The catalog reads property logo, gallery, facilities and important information from Channex details");}
  var room=new RoomInput(Guid.NewGuid(),id,"Apartamento 101",2,1,1,1,250m,"Descrição do apartamento",[],Enumerable.Repeat(ticket,10).ToArray(),"101");
  check((await post("/api/accommodations/rooms",room with{PhotoTickets=Enumerable.Repeat(ticket,11).ToArray()},csrf)).StatusCode==HttpStatusCode.BadRequest&&!remote.Writes.Any(w=>w.Resource=="room_types"),"Eleven photos are rejected before any Room is created");
  using var roomResponse=await post("/api/accommodations/rooms",room,csrf);using var roomDoc=JsonDocument.Parse(await roomResponse.Content.ReadAsStringAsync());check(roomResponse.IsSuccessStatusCode&&roomDoc.RootElement.GetProperty("confirmed").GetBoolean(),"Saving an apartment immediately creates and verifies the Room, photos and tariff");var roomId=roomDoc.RootElement.GetProperty("id").GetGuid();
  var roomBody=remote.Writes.Single(w=>w.Resource=="room_types").Body.GetProperty("room_type");check(roomBody.GetProperty("property_id").GetGuid()==id&&roomBody.GetProperty("content").GetProperty("photos").GetArrayLength()==10&&roomBody.GetProperty("count_of_rooms").GetInt32()==1,"The initial Room request includes all ten ordered photos and the correct parent building");check(roomBody.GetProperty("content").GetProperty("description").GetString()!.Contains("Quartos: 1"),"Room details are stored in the Channex description rather than local supplemental content");
  var writes=remote.Writes.Count;check((await post("/api/accommodations/rooms",room,csrf)).IsSuccessStatusCode&&remote.Writes.Count==writes,"Repeating apartment save cannot duplicate its Room, photos or tariff");
  using var catalog=await client.GetAsync("/api/accommodations");using var catalogDoc=JsonDocument.Parse(await catalog.Content.ReadAsStringAsync());var saved=catalogDoc.RootElement.GetProperty("rooms").EnumerateArray().Single(r=>r.GetProperty("id").GetGuid()==roomId);check(saved.GetProperty("photos").GetArrayLength()==10&&saved.GetProperty("bedrooms").GetInt32()==1&&saved.GetProperty("basePrice").GetDecimal()==250m,"Displayed photos, details and prices are read back from Channex");
  using(var scope=services.CreateScope()){var pms=scope.ServiceProvider.GetRequiredService<PmsService>();await pms.CreatePropertyAsync(new("LOCAL MUST NOT SHOW","hotel","BRL","UTC"));await scope.ServiceProvider.GetRequiredService<CatalogFiles>().Save("building-"+id,new BuildingContent{Input=building with{Address="FALSE LOCAL ADDRESS"}});}
  using var clean=await client.GetAsync("/api/accommodations");var text=await clean.Content.ReadAsStringAsync();check(!text.Contains("LOCAL MUST NOT SHOW")&&!text.Contains("FALSE LOCAL ADDRESS"),"Local drafts and local fallback fields cannot appear as Channex data");
  remote.OmitContactOnCreate=true;var beforeProperties=remote.Writes.Count(w=>w.Resource=="properties");var incomplete=building with{OperationId=Guid.NewGuid(),Title="Incomplete response"};check((await post("/api/accommodations/properties",incomplete,csrf)).StatusCode==HttpStatusCode.Conflict,"HTTP success without persisted contact data is not reported as a completed save");check((await post("/api/accommodations/properties",incomplete,csrf)).StatusCode==HttpStatusCode.Conflict&&remote.Writes.Count(w=>w.Resource=="properties")==beforeProperties+1,"Readback failure retries verification without duplicating the remote property");remote.OmitContactOnCreate=false;
  remote.LoseRoomResponse=true;var lost=room with{OperationId=Guid.NewGuid(),PhotoTickets=[]};check((await post("/api/accommodations/rooms",lost,csrf)).StatusCode==HttpStatusCode.ServiceUnavailable,"An unknown Room creation result is reported explicitly");remote.LoseRoomResponse=false;var before=remote.Writes.Count;check((await post("/api/accommodations/rooms",lost,csrf)).StatusCode==HttpStatusCode.Conflict&&remote.Writes.Count==before,"Uncertain remote creation cannot be repeated blindly");
  check(remote.Hosts.All(h=>h=="app.channex.io"),"All remote operations use the production host");auth.CurrentRole="proprietario";using(var ownerPortfolio=await client.GetAsync("/api/accommodations")){using var ownerData=JsonDocument.Parse(await ownerPortfolio.Content.ReadAsStringAsync());check(ownerPortfolio.IsSuccessStatusCode&&ownerData.RootElement.GetProperty("rooms").GetArrayLength()==0,"Owner without assignments receives an empty portfolio");}auth.CurrentRole="master";
 }
}
